"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[3123],{7826(e){e.exports=JSON.parse('{"title":"any \uc9c0\uc591\ud558\uae30\ub97c \uc9c0\ud5a5\ud558\uae30","date":"2025-02-07","coverUrl":"/kudzu-based-bench/assets/notion/3fa2a19f44ba7720.png","html":"<h2 data-notion-block-id=\\"18ee548d-8a8e-8052-b925-f69cf2c2ba18\\" id=\\"18ee548d-8a8e-8052-b925-f69cf2c2ba18\\"><code>any</code> \uc9c0\uc591\ud558\uae30\ub97c \uc9c0\ud5a5\ud558\uae30</h2><a href=\\"https://typescript-eslint.io/blog/avoiding-anys/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://typescript-eslint.io/blog/avoiding-anys/</a><p data-notion-block-id=\\"18ee548d-8a8e-8093-918f-f67dca6daea4\\"><code>any</code> \uc0ac\uc6a9\uc744 \uc9c0\uc591\ud574\uc57c \ud560 \ub54c, \ud544\uc694\ud55c <code>typescript-eslint</code>\uc18d\uc131\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \uc5b4\uca54 \uc218 \uc5c6\uc744 \ub54c\ub9cc <code>@typescript-eslint/no-explicit-any</code>\uc744 \uc0ac\uc6a9\ud558\uba74 \ub418\uaca0\uc9c0\ub9cc, \ud788\uc2a4\ud1a0\ub9ac \uae30\ub85d\uc744 \uc704\ud574 \ucf54\uba58\ud2b8\ub97c \uc7a5\ub824\ud558\ub294 \uc18d\uc131, \ud639\uc740 \ub0b4\uc7a5 \uae00\ub85c\ubc8c \ud0c0\uc785 \uc9c0\uc815\uc744 \uad6c\uccb4\uc801\uc73c\ub85c \ud558\ub294 <a href=\\"https://github.com/mattpocock/ts-reset\\"><code>ts-reset</code></a> \ucd94\ucc9c\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ucd94\uac00\ub85c window\uc5d0 \uc0bd\uc785\ub41c \uc18d\uc131\uc744 \uc0ac\uc6a9\ud558\uae30 \uc704\ud55c <a href=\\"https://www.totaltypescript.com/how-to-properly-type-window\\">declare \uc0ac\uc6a9\ubc95</a>\ub3c4 \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4</p><h2 data-notion-block-id=\\"18ee548d-8a8e-80ab-92a5-e2cfb1711e15\\" id=\\"18ee548d-8a8e-80ab-92a5-e2cfb1711e15\\">\ub2e8\ucd95\ud0a4\ub97c \uad6c\uc131\ud560 \ub54c \uc720\uc758\ud560 \uc810</h2><a href=\\"https://blog.duvallj.pw/posts/2025-01-10-all-javascript-keyboard-shortcut-libraries-are-broken.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.duvallj.pw/posts/2025-01-10-all-javascript-keyboard-shortcut-libraries-are-broken.html</a><p data-notion-block-id=\\"18ee548d-8a8e-80b8-9a39-f709ee1669d9\\">\ub2e8\ucd95\ud0a4\ub97c \uad6c\uc131\ud560 \uc218 \uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4 \uc911 deprecated\ub41c <code>keycode</code>, <code>which</code>, <code>keyIdentifier</code>\ub97c \uc0ac\uc6a9\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \ub9ce\uae30\uc5d0, \ub77c\uc774\ube0c\ub7ec\ub9ac \uac1c\ubc1c\uc790\ub098 \ud06c\ub85c\uc2a4 \ube0c\ub77c\uc6b0\uc800 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc790\uc5d0\uac8c \uad8c\uc7a5\ub418\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-8015-ae08-df3a1c7a7833\\" id=\\"18ee548d-8a8e-8015-ae08-df3a1c7a7833\\">Next.js app router \ub9ac\ubdf0</h2><a href=\\"https://beeps.dev/blog/nextjs-an-honest-review\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://beeps.dev/blog/nextjs-an-honest-review</a><p data-notion-block-id=\\"18ee548d-8a8e-8083-88e5-ea1430743943\\">Next.js 14\uc5d0 \ub300\ud55c \uc8fc\uad00\uc801\uc778 \ub9ac\ubdf0\uae00\uc785\ub2c8\ub2e4. \uc608\uc804\uc5d0\ub3c4 <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4dabcc7-9269-46bc-a2f2-ed10f9fcf35f#a7149fc6-b56a-405b-be3c-004fdbe51c8b\\">App router\uc5d0 \ub300\ud55c \uac1c\uc778\uc801\uc778 \ub9ac\ubdf0</a> \ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ffe0e0a6-901b-4f3e-8b9a-0e48601ad787#6e1950cf-ceb7-418a-a85a-e4b7aef10d94\\">Server Components\uc5d0 \ub300\ud55c \ub9ac\ubdf0</a>\uac00 \uc788\uc5c8\ub294\ub370, \ud604\uc7ac\uc5d0\ub3c4 \ube44\uc2b7\ud558\uac8c Server Components\uad00\ub828 \ubb38\uc81c\ub098 \uac1c\ubc1c\uc790 \uc778\uc2dd/\uc811\uadfc \uad00\ub828 \ubb38\uc81c\uac00 \ubaa8\ub450 \ud574\uacb0\ub41c \uac83 \uac19\uc9c0 \uc54a\uc544 \uc544\uc27d\ub124\uc694.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-8069-9989-ea2ae747e4dc\\" id=\\"18ee548d-8a8e-8069-9989-ea2ae747e4dc\\">JSDOM\uc744 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub294 \uc774\uc720</h2><a href=\\"https://www.epicweb.dev/why-i-won-t-use-jsdom\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicweb.dev/why-i-won-t-use-jsdom</a><p data-notion-block-id=\\"18ee548d-8a8e-802e-bb29-c7ae4ce52eaa\\">JSDOM\uc774 \ubb34\uc5c7\uc778\uc9c0 \uc18c\uac1c\ud558\uace0, \uc65c \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub294\uc9c0, \ub300\uccb4\ud560 \uc218 \uc788\ub294 \ubc29\ubc95\uc740 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c \uc800\uc790\uc758 \ub2e4\ub978 \uae00\uc778 <a href=\\"https://ones-to-watch.ethansup.net/news/post/ee307831cb464aafb912fff97004d37e#c591a4a0-9749-47c1-9c95-4838fa55356d\\">Global \ud328\uce58\uac00 \uc704\ud5d8\ud55c \uc774\uc720</a>\ub3c4 \ube44\uc2b7\ud55c \uacb0\uc744 \ub744\uc9c0\ub9cc \uc5ec\ub7ec \uc704\ud5d8\ud55c \uc810\uc744 \uc9da\uc5b4\uc8fc\ubbc0\ub85c \uc77d\uc5b4\ubcf4\uc2dc\uae38 \uad8c\uc7a5\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-805e-b413-d4c0a07a1a48\\" id=\\"18ee548d-8a8e-805e-b413-d4c0a07a1a48\\">192\ubc14\uc774\ud2b8 WASM \ucef4\ud30c\uc77c\ub7ec \ubd84\uc11d\ud558\uae30</h2><a href=\\"https://wasmgroundup.com/blog/wasm-compiler-in-a-tweet/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://wasmgroundup.com/blog/wasm-compiler-in-a-tweet/</a><p data-notion-block-id=\\"18ee548d-8a8e-8073-ad53-cd791ba4690f\\">192\ubc14\uc774\ud2b8\ub85c WASM\uc744 \uc2e4\ud589\ud558\ub294 \ucf54\ub4dc\ub97c \ubd84\uc11d\ud558\uba74\uc11c JS\uc5d0\uc11c \ubcf4\uc774\ub294 \ucd5c\uc18c\ud654(Minification) \uae30\ubc95\ub4e4\uacfc WASM \ubc14\uc774\ud2b8\uc758 \uad6c\uc131 \ubc29\uc2dd\uc744 \uc54c \uc218 \uc788\ub294 \uae00\uc785\ub2c8\ub2e4. WASM\uc5d0 \ub300\ud55c \uc804\ubc18\uc801\uc778 \uc9c0\uc2dd\ubcf4\ub2e4\ub294, WASM \ubc14\uc774\ub108\ub9ac \ud615\uc2dd\uc774\ub098 \uae30\uc220\uc744 \uc0b4\uc9dd \uc5ff\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-804f-9237-ce005f10ebbb\\" id=\\"18ee548d-8a8e-804f-9237-ce005f10ebbb\\">WebSocket \ud655\uc7a5\ud558\uae30</h2><a href=\\"https://composehq.com/blog/scaling-websockets-1-23-25\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://composehq.com/blog/scaling-websockets-1-23-25</a><p data-notion-block-id=\\"192e548d-8a8e-80cd-85dc-f1f65b179416\\">WebSocket \uae30\ubc18 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4 \ub54c \uc5b4\ub824\uc6c0\uc744 \uacaa\uc740 \ubd80\ubd84\ub4e4\uc744 \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5ec\ub7ec \uac00\uc9c0\uac00 \uc5f0\uacb0 \ub04a\uae40\uc5d0 \uad00\ud55c \uac83\uc774\uc5ec\uc11c, \uc5f0\uacb0 \ub04a\uae40\uc744 \uc5b4\ub5bb\uac8c \ub300\ube44\ud558\ub098\ub97c \uc54c\uc544\ub450\uae30\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18be548d-8a8e-80dc-beb3-d3c62568f740\\" id=\\"18be548d-8a8e-80dc-beb3-d3c62568f740\\">Electron\uc5d0 \ub300\ud55c \uc624\ud574</h2><a href=\\"https://felixrieseberg.com/things-people-get-wrong-about-electron/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://felixrieseberg.com/things-people-get-wrong-about-electron/</a><p data-notion-block-id=\\"18ee548d-8a8e-808b-9a3a-f2e8d9c8103e\\">Electron\uc740 \ub124\uc774\ud2f0\ube0c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc744 \ub9cc\ub4e4\uae30\uc5d0 \uc88b\uc740 \ub3c4\uad6c\uc774\uc9c0\ub9cc, \ubaa8\ub4e0 \uc694\uad6c\uc0ac\ud56d\uc5d0 \uc54c\ub9de\ub294 \ub3c4\uad6c\ub294 \uc544\ub2d9\ub2c8\ub2e4. <a href=\\"https://www.electronjs.org/docs/latest/why-electron\\">Electron\uc758 \uacf5\uc2dd \ubb38\uc11c\uc5d0 \uc788\ub294 Electron\uc744 \uc120\ud0dd\ud574\uc57c \ud558\ub294 \uc774\uc720</a>\uc5d0 \ubc18\ub300\ub418\ub294 \ub124\uc774\ud2f0\ube0c\ub97c \uc120\ud0dd\ud574\uc57c \ud558\ub294 \uc774\uc720\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-803d-88e7-e9b3191d3c15\\" id=\\"18ee548d-8a8e-803d-88e7-e9b3191d3c15\\">JS \uc2dc\uac04\uc5d0 \ub300\ud55c \uc5ed\uc0ac</h2><a href=\\"https://docs.timetime.in/blog/how-long-is-a-second-in-js/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://docs.timetime.in/blog/how-long-is-a-second-in-js/</a><p data-notion-block-id=\\"18ee548d-8a8e-800e-b3c2-c08575e9545a\\">\uc2dc\uac04 \ucc99\ub3c4\uc758 \uc18c\uac1c\uc5d0\uc11c \uc2dc\uc791\ud574\uc11c, \uadf8\ub85c\ubd80\ud130 \ubc1c\uc0dd\ud55c \ubb38\uc81c\ub97c \uc5b4\ub5bb\uac8c \ud574\uacb0\ud588\ub294\uc9c0 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uac1c\ubc1c\uc5d0 \uc911\uc694\ud55c \uac1c\ub150\uc740 \uc544\ub2c8\uc9c0\ub9cc, \ud765\ubbf8\ub85c\uc6b4 \uae00\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-8021-a8bf-fcf3a507ffbb\\" id=\\"18ee548d-8a8e-8021-a8bf-fcf3a507ffbb\\">Tree view\ub97c \uc811\uadfc\uc131 \uc88b\uac8c \ub9cc\ub4e4\uae30</h2><a href=\\"https://github.blog/engineering/user-experience/considerations-for-making-a-tree-view-component-accessible/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/engineering/user-experience/considerations-for-making-a-tree-view-component-accessible/</a><p data-notion-block-id=\\"18ee548d-8a8e-8035-b318-c313fff78a59\\">Github\uc5d0\uc11c Tree view \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc811\uadfc\uc131 \uc88b\uac8c \ub9cc\ub4e4\uae30 \uc704\ud574 \uc5b4\ub5a4 \uc0ac\ud56d\uc744 \uace0\ub824\ud588\uace0, \uc5b4\ub5bb\uac8c \uc801\uc6a9\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"193e548d-8a8e-8040-b3f3-d92ec3215fe1\\" id=\\"193e548d-8a8e-8040-b3f3-d92ec3215fe1\\">\ubc18\uc751\ud615 \ub514\uc790\uc778 \ubc30\uc6b0\uae30</h2><a href=\\"https://web.dev/learn/design/welcome\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://web.dev/learn/design/welcome</a><p data-notion-block-id=\\"193e548d-8a8e-807c-8b94-e30465bb9385\\">\uc608\uc804\uc5d0 \ub098\uc628 \ubc18\uc751\ud615 \ub514\uc790\uc778\uc5d0 \ub300\ud55c \uc790\ub8cc\uc774\uc9c0\ub9cc, \ub9ce\uc774 \uc9c0\ub098\uce60\ub9cc\ud55c \ub2e4\uc591\ud55c \ubaa8\ubc14\uc77c \ud658\uacbd\uc758 \uc228\uaca8\uc9c4 \uc694\uad6c\uc0ac\ud56d, \uc798 \ubaa8\ub974\ub294 CSS \uc18d\uc131\ub3c4 \uc18c\uac1c\ud574\uc8fc\uae30 \ub54c\ubb38\uc5d0, \ubc18\uc751\ud615 \ub514\uc790\uc778\uc744 \ub9cc\ub4e4 \ub54c \uc9c0\ub098\ucce4\ub358 \uac83\ub4e4\uc744 \ub418\uc0c8\uae30\uae30\uc5d0 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"18ee548d-8a8e-8016-89d0-f0fc529a6502\\" id=\\"18ee548d-8a8e-8016-89d0-f0fc529a6502\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://standardschema.dev/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://standardschema.dev/</a><a href=\\"https://tailwindcss.com/blog/tailwindcss-v4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tailwindcss.com/blog/tailwindcss-v4</a><a href=\\"https://www.totaltypescript.com/erasable-syntax-only\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/erasable-syntax-only</a><a href=\\"https://github.com/facebook/create-react-app/issues/17004\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/facebook/create-react-app/issues/17004</a><a href=\\"https://developer.mozilla.org/en-US/blog/javascript-temporal-is-coming/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.mozilla.org/en-US/blog/javascript-temporal-is-coming/</a><p data-notion-block-id=\\"18ee548d-8a8e-8097-9b00-de6d21321680\\">\uccab\ubc88\uc9f8 \uae00\uc740 runtime validation \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ud45c\uc900\uc778 Standard Schema\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc5ec\ub7ec\uac00\uc9c0 \uc720\ud6a8\uc131 \uac80\uc99d \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ube60\ub974\uac8c \ubc14\uafc0 \uc218 \uc788\uac8c \ub3d5\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. \ub450 \ubc88\uc9f8\ub294 \uc5ec\ub7ec CSS \uc9c0\uc6d0\uacfc \ube60\ub978 \uc131\ub2a5\uc758 \uc5d4\uc9c4\uc774 \uc801\uc6a9\ub41c Tailwind 4\ubc84\uc804\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc138 \ubc88\uc9f8\ub294 TypeScript 5.8\ubc84\uc804(\ud604\uc7ac\ub294 \ubca0\ud0c0\uc0c1\ud0dc)\uc5d0\uc11c \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/156e548d-8a8e-8024-aec1-fd27c897c295#ts-blank-space\uc640-\ud2b8\ub79c\uc2a4\ud30c\uc77c-\uac1c\uc120\\">ts-blank-space</a>\ub098 <a href=\\"https://ones-to-watch.ethansup.net/news/post/17ee548d-8a8e-8045-8a26-f5dfa6d03856#nodejs\uc5d0\uc11c-typescript\ub97c-\uc0ac\uc6a9\ud560-\uc218-\uc788\ub2e4-\uadf8\uc804\uc5d0\\">Node.js\uc758 type stripping</a>\uc744 typescript\uc5d0\uc11c\ub3c4 \uc9c0\uc6d0\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \ub124\ubc88\uc9f8\ub294 React 19\uac00 \ub418\uba74\uc11c CRA\uac00 deprecated\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc744 \uc811\ud558\uc9c0 \ubabb\ud560 \uc218\ub3c4 \uc788\uae30\uc5d0 CRA CLI\ub098 \ubb38\uc11c\uc5d0 deprecated\ub418\uc5c8\ub2e4\ub294 \uac83\uc744 \uc54c\ub9ac\uc790\ub294 issue\uc785\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/a550d266-f5e9-45ae-b84e-2cc1a0180de2#javascript\uc758-\uc0c8\ub85c\uc6b4-\ub0a0\uc9dc-\uacc4\uc0b0-api\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 Temporal API</a>\uac00 \uac1c\ubc1c\uc911\uc784\uc744 \uc54c\ub9ac\ub294 \uae00\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"193e548d-8a8e-8039-b0d0-d37d4c05b563\\"></p>"}')}}]);